entries[238735] = { ["name"] = "Tüftelkiste: Nitrobooster", ["text"] = "Benötigt Stufe 45\nBenutzen: Aktiviert eine Reihe von Strahlen, um Eure Bewegungsgeschwindigkeit für bis zu 8 Sek. um bis zu 160% zu erhöhen." }
entries[238736] = { ["name"] = "Tüftelkiste: Magnetversetzung", ["text"] = "Benötigt Stufe 45\nBenutzen: Unterbricht ein Magnetfeld zwischen Euch und Eurem gegnerischen Ziel in der Nähe und schleudert Euch beide fort.\n\nKann nur Ziele bis zu 2 Stufen über Euch betreffen. Einige Ziele können nicht versetzt werden. Ziele können nur einmal alle 2 Min. von diesem Effekt betroffen werden." }
entries[238737] = { ["name"] = "Tüftelkiste", ["text"] = "Handwerksmaterial\n\"Ein einfaches Kontrollmodul das von Ingenieuren beim Herstellen von Tüfteleien verwendet wird.\"" }
entries[238781] = { ["name"] = "Halbwegs sicherer Transporter: Neu-Avalon", ["text"] = "Wird bei Benutzung gebundenSchmuck\nBenötigt Stufe 60\nBenötigt Ingenieurskunst (290)\nBenutzen: Werft jede Vorsicht über Bord und probiert das Teleportationsgerät eines Goblins aus. Hoffentlich kommt Ihr in einem Stück in Neu-Avalon an. (4 Std. Abklingzeit)" }
entries[238782] = { ["name"] = "Bauplan: Tüftelkiste", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (250)\n\"Lehrt Euch, wie man eine Tüftelkiste herstellt.\"" }
entries[238783] = { ["name"] = "Bauplan: Tüftelkiste: Teleportation", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (260)\n\"Lehrt Euch, wie man die Tüftelkiste: Teleportation herstellt.\"" }
entries[238784] = { ["name"] = "Bauplan: Tüftelkiste: Nitrobooster", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (260)\n\"Lehrt Euch, wie man die Tüftelkiste: Nitrobooster herstellt.\"" }
entries[238785] = { ["name"] = "Bauplan: Tüftelkiste: Magnetversetzung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (260)\n\"Lehrt Euch, wie man die Tüftelkiste: Magnetversetzung herstellt.\"" }
entries[238786] = { ["name"] = "Bauplan: Tüftelei: Teleportation", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (280)\nVerbessert Euren Gürtel, damit er folgenden Effekt bietet:\n\nTeleportiert Euch 20 Meter vorwärts.\n\"Lehrt Euch, wie man die Tüftelei: Teleportation herstellt.\"" }
entries[238787] = { ["name"] = "Bauplan: Tüftelei: Nitrobooster", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (280)\nVerbessert Euren Gürtel, damit er folgenden Effekt bietet:\n\nAktiviert eine Reihe von Strahlen, um Eure Bewegungsgeschwindigkeit für bis zu 8 Sek. um bis zu 160% zu erhöhen.\n\"Lehrt Euch, wie man die Tüftelei: Nitrobooster herstellt.\"" }
entries[238788] = { ["name"] = "Bauplan: Tüftelei: Magnetversetzung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (280)\nVerbessert Euren Gürtel, damit er folgenden Effekt bietet:\n\nUnterbricht ein Magnetfeld zwischen Euch und Eurem gegnerischen Ziel in der Nähe und schleudert Euch beide fort.\n\nKann nur Ziele bis zu 2 Stufen über Euch betreffen. Einige Ziele können nicht versetzt werden. Ziele können nur einmal alle 2 Min. von diesem Effekt betroffen werden.\n\"Lehrt Euch, wie man die Tüftelei: Magnetversetzung herstellt.\"" }
entries[238789] = { ["name"] = "Bauplan: Halbwegs sicherer Transporter: Neu-Avalon", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (300)\n\"Lehrt Euch, wie man einen halbwegs sicheren Transporter: Neu-Avalon herstellt.\"" }
entries[238794] = { ["name"] = "Widerwärtige Essensreste", ["text"] = "Questgegenstand\n\"Vielleicht ist der Hungertod doch eine Option.\"" }
entries[238811] = { ["name"] = "Saftiger Apfel", ["text"] = "Questgegenstand\n\"Frisch vom Feld.\"" }
entries[238830] = { ["name"] = "Apfelfernrohr", ["text"] = "Questgegenstand\nBenutzen: Ermöglicht Euch, auf der Suche nach Äpfeln in weite Entfernungen zu sehen.\n\"Wird von den faulsten Bauern dazu verwendet, aus dem Komfort der eigenen vier Wände die Ernte zu beaufsichtigen.\"" }
entries[238831] = { ["name"] = "Apfelseil", ["text"] = "Questgegenstand\nBenutzen: Stehlt einen Apfel aus sicherer Entfernung.\n\"Ist nur ein einfaches Seil.\"" }
entries[238899] = { ["name"] = "Erlesener Fisch", ["text"] = "Questgegenstand\n\"Eure Angelfertigkeiten sind nicht ausgeprägt genug, um einen Großteil dieser Fische zu identifizieren. Glücklicherweise ist das nicht Euer Problem.\"" }
entries[238925] = { ["name"] = "Scharlachroter Köcher", ["text"] = "Wird beim Anlegen gebunden\n30 Platz Köcher\nBenötigt Stufe 60\nAnlegen: Erhöht das Distanzangriffstempo um 15%." }
entries[238926] = { ["name"] = "Scharlachroter Munitionsbeutel", ["text"] = "Wird beim Anlegen gebunden\n30 Platz Munitionsbeutel\nBenötigt Stufe 60\nAnlegen: Erhöht das Distanzangriffstempo um 15%." }
entries[238927] = { ["name"] = "Muster: Scharlachroter Köcher", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (275)\n\"Lehrt Euch, wie man einen scharlachroten Köcher herstellt.\"" }
entries[238928] = { ["name"] = "Muster: Scharlachroter Munitionsbeutel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (275)\n\"Lehrt Euch, wie man einen scharlachroten Munitionsbeutel herstellt.\"" }
entries[238935] = { ["name"] = "Sanft gequältes Fleisch", ["text"] = "Questgegenstand\n\"Wenn Ihr die grünen Stellen wegschneidet, wird schon keiner was bemerken.\"" }
entries[238945] = { ["name"] = "Caladbrocken", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n334 - 501 Schaden Tempo 4.30\n(97.09 Schaden pro Sekunde)\n+30 Stärke\n+10 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 300 / 300\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nTrefferchance: Das Gewicht von Caladbrocken wirft 4 Sek. lang alle Gegnern in der Nähe zu Boden.\nAnlegen: Bewegungsgeschwindigkeit um 10% verringert.\n\"Das Schwert und der Stein\"" }
entries[238960] = { ["name"] = "Rüstmeisterkiste", ["text"] = "Questgegenstand\nBenutzen: Legt ein Teil hergestellter Ausrüstung des Scharlachroten Kreuzzugs in die Kiste. Der Gegenstand wird dadurch dauerhaft vernichtet." }
entries[238961] = { ["name"] = "Caladschneide", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n339 - 509 Schaden Tempo 3.90\n(108.72 Schaden pro Sekunde)\n+50 Stärke\n+15 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eurer Angriffstempo um 2%.\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nBenutzen: Die Caladschneide wird 20 Sek. lang erneut von der Erde verschlungen, wodurch die Bewegungsgeschwindigkeit um 50% verringert wird. Wenn Ihr Euch bewegt, erhöht sich Eure Bewegungsgeschwindigkeit alle 2 Sekunden. Wenn Ihr in einen Gegner kracht, fügt Ihr diesem 300 bis 2700 Feuerschaden zu, wobei Ihr alle gegnerischen Spielercharaktere zurückstoßt und diesen Effekt beendet. (2 Min Abklingzeit)\n\"Eine uralte Klinge, die vom Scharlachroten Kreuzzug geheim gehalten wird. Weist leichte Gebrauchsspuren auf.\"" }
entries[238985] = { ["name"] = "Schwere Kiste", ["text"] = "Questgegenstand\n\"Bringt sie zum scharlachroten Rüstmeister, um Euren Wert zu beweisen.\"" }
entries[239010] = { ["name"] = "Griff des Aschenbringers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n99 - 162 Schaden Tempo 2.00\n(65.25 Schaden pro Sekunde)\nHaltbarkeit 15 / 15\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nBenutzen: Versucht, Kontakt zum Willen des Aschenbringers aufzunehmen. (4 Min Abklingzeit)" }
entries[239011] = { ["name"] = "Splitter kristallisierten Lichts", ["text"] = "Wird beim Aufheben gebunden" }
entries[239012] = { ["name"] = "Span kristallisierten Lichts", ["text"] = "Wird beim Aufheben gebunden" }
entries[239013] = { ["name"] = "Kristalline Axt", ["text"] = "Wird beim Aufheben gebunden\n\"Klingen des Lichts, wahrhaftig.\"" }
entries[239016] = { ["name"] = "Weihsalz", ["text"] = "Handwerksmaterial\n\"Wird häufig von des Kreuzzüglern verwendet, um Unglück zu vertreiben. Lässt sich praktischerweise auch gut zum Kochen verwenden.\"" }
entries[239017] = { ["name"] = "Erlesene Gewürze", ["text"] = "Handwerksmaterial\n\"Eine hochgradig regulierte Ware. Der direkte Kauf oder Verkauf wäre unklug. Wird von Köchen begehrt, die Festmahle zubereiten.\"" }
entries[239021] = { ["name"] = "Carries Kochbuch", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\nBenutzen: Lehrt Euch, wie man die begehrtesten Festtagsrezepte von Carrie Herdfeuer kocht." }
entries[239060] = { ["name"] = "Wille des Berges", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Streitkolben\n169 - 316 Schaden Tempo 2.90\n(83.62 Schaden pro Sekunde)\n+17 Stärke\n+5 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\nTrefferchance: Ruft den Willen des Berges an, wodurch der verursachte körperliche Schaden 15 Sek. lang um 5%, die Rüstung um 500 und die Größe um 20% erhöht werden.\n\"Einst ein mächtiger Schmiedehammer, ist dieses wahrhaft erstaunliche Stück Handwerkskunst noch inspirierender, wenn man ihn in Händen hält.\"" }
entries[239092] = { ["name"] = "Bescheuert beschrifteter Brief", ["text"] = "Questgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[239097] = { ["name"] = "Schlüssel zur Kathedrale", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig" }
entries[239117] = { ["name"] = "Kelch des des Kreuzzüglers", ["text"] = "Wird beim Aufheben gebunden\n\"Bringt ihn zusammen mit einem entsprechenden Gegenstand aus dem herstellbaren Set des scharlachroten des Kreuzzüglers zu Byron Steelblade in Neu-Avalon, um ihn gegen einen Klassensetgegenstand einzutauschen.\"" }
entries[239119] = { ["name"] = "Heiliger Pfeil", ["text"] = "Questgegenstand\n\"Geheiligt sei der Pfeil, der unseren Feinden ihre Buße zukommen lässt.\"" }
entries[239147] = { ["name"] = "Kreuzzüglerknappsack", ["text"] = "Wird beim Anlegen gebunden\n24 Platz Behälter" }
entries[239148] = { ["name"] = "Blutrote Morgengespinsttasche", ["text"] = "Wird beim Anlegen gebunden\n30 Platz Behälter" }
entries[239149] = { ["name"] = "Muster: Kreuzzüglerknappsack", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (250)\n\"Lehrt Euch, wie man einen Kreuzzüglerknappsack herstellt.\"" }
entries[239150] = { ["name"] = "Muster: Blutrote Morgengespinsttasche", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (290)\n\"Lehrt Euch, wie man eine blutrote Morgengespinsttasche herstellt.\"" }
entries[239196] = { ["name"] = "Verdorbene lichtgeschmiedete Klinge", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nKlassen: Krieger , Paladin , Jäger" }
entries[239197] = { ["name"] = "Neugeschmiedete Klinge des Aschenbringers", ["text"] = "Wird beim Aufheben gebunden" }
entries[239215] = { ["name"] = "Verkohltes Emblem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60" }
entries[239216] = { ["name"] = "Lichtgeschmiedetes Eisen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Krieger , Paladin , Jäger" }
entries[239218] = { ["name"] = "Notizen der Steinformer", ["text"] = "Questgegenstand\nEinzigartig\n\"Das Dokument ist in einer unsauberen Kurzschrift verfasst, doch was Ihr davon ausmachen könnt, legt nahe, dass diese Pläne und Projektnotizen das Produkt eines wahrhaft genialen Handwerkers sind.\"" }
entries[239219] = { ["name"] = "Emblem des Aschenbringers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\nBenutzen: Kombiniert das Emblem des Aschenbringers, die neugeschmiedete Klinge des Aschenbringers und den Griff des Aschenbringers." }
entries[239222] = { ["name"] = "Bauplan: Aufstellbäumchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (250)\n\"Lehrt Euch, wie man ein Aufstellbäumchen herstellt.\"" }
entries[239223] = { ["name"] = "Hausrequisite", ["text"] = "Questgegenstand\n\"Wirklich überzeugend, zumindest im Kontext einer Aufführung oder Oper.\"" }
entries[239225] = { ["name"] = "Stilvoller Federkiel", ["text"] = "Questgegenstand\n\"Ihr könnt Euch kaum vorstellen, wie befriedigend es sein muss, die eigene Unterschrift damit zu setzen.\"" }
entries[239246] = { ["name"] = "Zischluntes Einkaufsliste", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine Liste mit Gegenständen, die der Autor wie sie ihm in den Sinn kamen niedergeschrieben hat.\"\n<Zum Lesen rechtsklicken>" }
entries[239248] = { ["name"] = "Scharlachrote Plunderkiste", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält allerlei rumliegenden Plunder. Manchmal allerdings auch etwas Wertvolles von einem tollkühnen Abenteurer.\"\n<Zum Öffnen rechtsklicken>" }
entries[239292] = { ["name"] = "Forgewrights Notizen", ["text"] = "Questgegenstand\nEinzigartig\n\"Enthält die gesammelten Gedanken und Werke von Franclorn Forgewright.\"" }
entries[239301] = { ["name"] = "Verderbter Aschenbringer", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n357 - 536 Schaden Tempo 3.80\n(117.50 Schaden pro Sekunde)\n+53 Stärke\n-30 Ausdauer\nHaltbarkeit 145 / 145\nBenötigt Stufe 60\nAnlegen: Der Träger wird vom Willen des Aschenbringers erfüllt.\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\nTrefferchance: Stiehlt 475 bis 525 Gesundheit von bis zu 5 Gegnern und gewährt Euch pro betroffenem Gegner 30 Stärke oder Beweglichkeit. Bis zu 5-mal stapelbar.\n\"Klinge des Scharlachroten Hochlords\"" }
entries[239302] = { ["name"] = "Gürtel der scharlachroten Uniform", ["text"] = "Questgegenstand\n\"Ein dichter Lederriemen mit einer schweren Stahlschnalle. Ein wahrhaft meisterhafter Gürtel, der bereit dafür ist, durch skrupellose Tüfteleien verschandelt zu werden.\"" }
entries[239316] = { ["name"] = "Triangulationssamophlang", ["text"] = "Questgegenstand\nBenötigt Ingenieurskunst (1)\nBenutzen: Verwendet das Gerät an einem designierten Triangulationspunkt, um Zischlunte bei der Kalibrierung seines Teleporters zu helfen. (10 Sek. Abklingzeit)" }
entries[239512] = { ["name"] = "Handgelenke des Lichtbrechers", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nHandgelenke Platte\n477 Rüstung\n+29 Stärke\n+10 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 55 / 55\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht Eurer Angriffstempo um 1%.\n\nKriegsplatte des Lichtbrechers (0/8)\nGroßhelm des Lichtbrechers\nSchultern des Lichtbrechers\nKürass des Lichtbrechers\nGürtel des Lichtbrechers\nTassetten des Lichtbrechers\nSchienbeinschützer des Lichtbrechers\nHandgelenke des Lichtbrechers\nHandschutz des Lichtbrechers\n(2) Set : Der Schaden Eurer Fähigkeiten 'Heldenhafter Stoß', 'Spalten' und 'Rasanter Schlag' ist um 20% erhöht, während Ihr Euch in Kampfhaltung oder Berserkerhaltung befindet. Eure Fähigkeit 'Spalten' trifft 1 $|zusätzliches Ziel:zusätzliche Ziele; und kann 'Blutwoge' auslösen.\n(4) Set : Immer, wenn Ihr ein Ziel mit 'Wirbelwind' 'Heldenhafter Stoß', 'Rasanter Schlag' oder 'Spalten' trefft, wird der Schaden Eures nächsten Einsatzes von 'Zerschmettern' um 20% erhöht. Bis zu 5-mal stapelbar.\n(6) Set : Jedes Mal, wenn 'Tiefe Wunden' Schaden verursacht, wird die verbleibende Abklingzeit von 'Wirbelwind' um 3 Sek. verringert. 'Wirbelwind' fügt Zielen, die von Eurem Effekt 'Tiefe Wunden' betroffen sind, 100% mehr Schaden zu.", ["unresolvedValues"] = true }
entries[239513] = { ["name"] = "Gürtel des Lichtbrechers", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nTaille Platte\n613 Rüstung\n+36 Stärke\n+10 Beweglichkeit\n+18 Ausdauer\nHaltbarkeit 55 / 55\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht Eurer Angriffstempo um 2%.\n\nKriegsplatte des Lichtbrechers (0/8)\nGroßhelm des Lichtbrechers\nSchultern des Lichtbrechers\nKürass des Lichtbrechers\nGürtel des Lichtbrechers\nTassetten des Lichtbrechers\nSchienbeinschützer des Lichtbrechers\nHandgelenke des Lichtbrechers\nHandschutz des Lichtbrechers\n(2) Set : Der Schaden Eurer Fähigkeiten 'Heldenhafter Stoß', 'Spalten' und 'Rasanter Schlag' ist um 20% erhöht, während Ihr Euch in Kampfhaltung oder Berserkerhaltung befindet. Eure Fähigkeit 'Spalten' trifft 1 $|zusätzliches Ziel:zusätzliche Ziele; und kann 'Blutwoge' auslösen.\n(4) Set : Immer, wenn Ihr ein Ziel mit 'Wirbelwind' 'Heldenhafter Stoß', 'Rasanter Schlag' oder 'Spalten' trefft, wird der Schaden Eures nächsten Einsatzes von 'Zerschmettern' um 20% erhöht. Bis zu 5-mal stapelbar.\n(6) Set : Jedes Mal, wenn 'Tiefe Wunden' Schaden verursacht, wird die verbleibende Abklingzeit von 'Wirbelwind' um 3 Sek. verringert. 'Wirbelwind' fügt Zielen, die von Eurem Effekt 'Tiefe Wunden' betroffen sind, 100% mehr Schaden zu.", ["unresolvedValues"] = true }
entries[239514] = { ["name"] = "Handschutz des Lichtbrechers", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nHände Platte\n681 Rüstung\n+35 Stärke\n+8 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 55 / 55\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\nAnlegen: Erhöht Eurer Angriffstempo um 2%.\n\nKriegsplatte des Lichtbrechers (0/8)\nGroßhelm des Lichtbrechers\nSchultern des Lichtbrechers\nKürass des Lichtbrechers\nGürtel des Lichtbrechers\nTassetten des Lichtbrechers\nSchienbeinschützer des Lichtbrechers\nHandgelenke des Lichtbrechers\nHandschutz des Lichtbrechers\n(2) Set : Der Schaden Eurer Fähigkeiten 'Heldenhafter Stoß', 'Spalten' und 'Rasanter Schlag' ist um 20% erhöht, während Ihr Euch in Kampfhaltung oder Berserkerhaltung befindet. Eure Fähigkeit 'Spalten' trifft 1 $|zusätzliches Ziel:zusätzliche Ziele; und kann 'Blutwoge' auslösen.\n(4) Set : Immer, wenn Ihr ein Ziel mit 'Wirbelwind' 'Heldenhafter Stoß', 'Rasanter Schlag' oder 'Spalten' trefft, wird der Schaden Eures nächsten Einsatzes von 'Zerschmettern' um 20% erhöht. Bis zu 5-mal stapelbar.\n(6) Set : Jedes Mal, wenn 'Tiefe Wunden' Schaden verursacht, wird die verbleibende Abklingzeit von 'Wirbelwind' um 3 Sek. verringert. 'Wirbelwind' fügt Zielen, die von Eurem Effekt 'Tiefe Wunden' betroffen sind, 100% mehr Schaden zu.", ["unresolvedValues"] = true }
