entries[239694] = { ["name"] = "Schwur des Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBeschwört Climgefahr, das Reittier der Hochkommandantin. Geschwindigkeit um 100% erhöht.\n\"Lernt, wie Ihr Climgefahr, das Reittier des Hochgenerals, beschwört oder wieder freigebt. Dies ist ein sehr schnelles Reittier.\"" }
entries[239695] = { ["name"] = "Scharlachrotes Ross", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Beschwört ein reitbares scharlachrotes Ross oder gibt es frei. Das ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)" }
entries[239696] = { ["name"] = "Griff des Aschenbringers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nHaltbarkeit 15 / 15\nBenötigt Stufe 60\n\"Selbst in Stücke geschlagen scheint diese Klinge eine Aura düsteren Unheils zu verströmen.\"" }
entries[239698] = { ["name"] = "Morgengespinststoff", ["text"] = "Questgegenstand\n\"Kleine Stofffetzen und Fäden, die auf geheimnisvolle Weise zum Webstuhl des Kreuzzüglers gezogen wurden. Werden scheinbar verwendet, um heilige Gewänder herzustellen.\"" }
