entries[240018] = { ["name"] = "Zischluntes Tüftelhandbuch", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (250)\nBenutzen: Lehrt Euch, wie man Gürtel mit wiederverwendbaren Tüfteleien verbessert.\n\"Eigentum von Zischlunte.\"" }
entries[240020] = { ["name"] = "Beinschützer der Inquisition", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nBeine Platte\n954 Rüstung\n+17 Ausdauer\n+24 Intelligenz\nHaltbarkeit 120 / 120\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Erhöht Euer Zaubertempo um 1%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 99 Gesundheit und den verursachten Schaden um bis zu 33.\n\nRüstung der Inquisition (0/8)\nKopfstück der Inquisition\nSchiftung der Inquisition\nTunika der Inquisition\nGurt der Inquisition\nBeinschützer der Inquisition\nStiefel der Inquisition\nHandgelenksschutz der Inquisition\nHandschützer der Inquisition\n(2) Set : 'Handauflegung' gewährt Euch 30 Sek. lang 20% Zaubertempo und verringert die globale Abklingzeit Eurer nächsten 5 Einsätze von 'Göttliches Licht', 'Heiliges Licht', 'Lichtblitz' und 'Heiliger Schock' um 0.5 Sek.\n(4) Set : Eure 'Flamme des Glaubens' wird jetzt auch ausgelöst, wenn Ihr das Ziel Eurer 'Flamme des Glaubens' heilt, allerdings mit 50% verringerter Effektivität.\n(6) Set : 25% Eurer verursachten Heilung werden zusätzlich auf das Ziel Eurer 'Flamme des Glaubens' übertragen." }
