entries[240022] = { ["name"] = "Stiefel der Inquisition", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nFüße Platte\n749 Rüstung\n+13 Ausdauer\n+15 Intelligenz\nHaltbarkeit 75 / 75\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht Euer Zaubertempo um 2%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 68 und den verursachten Schaden um bis zu 23.\n\nRüstung der Inquisition (0/8)\nKopfstück der Inquisition\nSchiftung der Inquisition\nTunika der Inquisition\nGurt der Inquisition\nBeinschützer der Inquisition\nStiefel der Inquisition\nHandgelenksschutz der Inquisition\nHandschützer der Inquisition\n(2) Set : 'Handauflegung' gewährt Euch 30 Sek. lang 20% Zaubertempo und verringert die globale Abklingzeit Eurer nächsten 5 Einsätze von 'Göttliches Licht', 'Heiliges Licht', 'Lichtblitz' und 'Heiliger Schock' um 0.5 Sek.\n(4) Set : Eure 'Flamme des Glaubens' wird jetzt auch ausgelöst, wenn Ihr das Ziel Eurer 'Flamme des Glaubens' heilt, allerdings mit 50% verringerter Effektivität.\n(6) Set : 25% Eurer verursachten Heilung werden zusätzlich auf das Ziel Eurer 'Flamme des Glaubens' übertragen." }
entries[240023] = { ["name"] = "Unterarmschienen der Inquisition", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nHandgelenke Platte\n477 Rüstung\n+29 Stärke\n+10 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 55 / 55\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n\nKriegsplatte der Inquisition (0/8)\nHelm der Inquisition\nSchulterplatten der Inquisition\nBrustplatte der Inquisition\nGürtel der Inquisition\nGamaschen der Inquisition\nSchienbeinschützer der Inquisition\nUnterarmschienen der Inquisition\nHandschuhe der Inquisition\n(2) Set : Während Ihr eine Zweihandwaffe ausgerüstet habt, gewähren Euch 'Kreuzfahrerstoß' und 'Exorzismus' Heilige Kraft und erhöhen den von Euch verursachten Heiligschaden um 10%. Bis zu 3-mal stapelbar. (100ms Abklingzeit)\n(4) Set : Euer 'Göttlicher Sturm', 'Heiliger Schock' und 'Heiliger Zorn' verbrauchen Eure gesamte Heilige Kraft und verursachen 100% mehr Schaden pro angesammelter Heiliger Kraft. Hat gegen Ziele, die von Spielercharakteren kontrolliert werden, eine Effektivität von 50%.\n(6) Set : Wenn Ihr Heilige Kraft verbraucht, wird Eure Angriffskraft 10 Sek. lang um 15% pro verbrauchter Heiliger Kraft erhöht." }
