entries[240837] = { ["name"] = "Schicksalsfäden", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n177 - 330 Schaden Tempo 3.60\n(70.42 Schaden pro Sekunde)\n+21 Beweglichkeit\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Chance von 10%, dass Distanzangriffe einen Schicksalsstrang erzeugen, sodass Ihr aus der Bewegung heraus einen Distanzangriff einsetzen könnt. Stränge können bis zu 5-mal gestapelt werden und halten 20 Sek. lang an.\nBenutzen: Erzeugt sofort 3 Schicksalsstränge. (1 Min, 20 Sek. Abklingzeit)" }
entries[240839] = { ["name"] = "Thal'kituun, der ungesehene Gast", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Dolch\n23 - 84 Schaden Tempo 1.30\n(41.15 Schaden pro Sekunde)\n100 Rüstung\n+15 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 144.\nAnlegen: Verteidigung +7." }
entries[240841] = { ["name"] = "Wache der Hochkommandantin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Schwert\n70 - 131 Schaden Tempo 1.20\n(83.75 Schaden pro Sekunde)\n+14 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\nAnlegen: Verteidigung +12.\nAnlegen: Schwerter +3.\nTrefferchance: Erhöht 10 Sek. lang die Verteidigung um 20 und die Rüstung um 750." }
entries[240842] = { ["name"] = "Scharlachroter Seuchenbringer", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n157 - 236 Schaden Tempo 3.60\n(54.58 Schaden pro Sekunde)\n150 Rüstung\n+24 Stärke\n+14 Beweglichkeit\n+48 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\nAnlegen: Verteidigung +7.\nAnlegen: Bei einem Nahkampfangriff besteht die Chance, Euren Gegner mit einer Seuche zu belegen, wodurch Gegner innerhalb von 8 Metern um den Zaubernden 12 Sek. lang alle 2 Sek. 100 Naturschaden erleiden. Das Angriffstempo dieser Ziele wird zudem um 15% verringert.\nAnlegen: +756 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt." }
entries[240843] = { ["name"] = "Starterpistole", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n91 - 170 Schaden Tempo 2.00\n(65.25 Schaden pro Sekunde)\n+11 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\nAnlegen: Verteidigung +7.\nAnlegen: Ein regulärer Distanzangriff auf ein Ziel bereitet Euch auf die Schlacht vor, wodurch 15 Sek. lang Eure Verteidigung um 20 und Euer Nahkampfangriffstempo um 10% erhöht wird." }
entries[240844] = { ["name"] = "Putress' Stecken", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n159 - 296 Feuerschaden Tempo 1.50\n(151.67 Schaden pro Sekunde)\n50 Rüstung\n+18 Ausdauer\nHaltbarkeit 75 / 75\nKlassen: Hexenmeister\nBenötigt Stufe 60\nAnlegen: Verteidigung +5.\nBenutzen: Verringert die Zauberzeit und die globale Abklingzeit von 'Sengender Schmerz' und 'Schattenspalten' 15 Sek. lang um 0.5 Sek. (2 Min Abklingzeit)" }
