entries[240919] = { ["name"] = "Wiederheerer", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Axt\n330 - 496 Schaden Tempo 3.80\n(108.68 Schaden pro Sekunde)\n+44 Stärke\n+31 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\nTrefferchance: Ihr greift 9 Sek. lang alle Gegner in der Nähe an und verursacht Waffenschaden plus alle 1.5 Sek. zusätzlich 200 Schaden." }
entries[240920] = { ["name"] = "Leogan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blazefury] (1)\nZweihändig Schwert\n148 - 222 Schaden Tempo 1.70\n(108.82 Schaden pro Sekunde)\n+47 Stärke\n+24 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Fügt Euren Nahkampfangriffen 2 Heiligschaden hinzu.\nAnlegen: Verbessert Eure Trefferchance mit allen Heiligzaubern um 3%.\nAnlegen: Erhöht Eurer Angriffstempo um 1%.\nAnlegen: Verringert die globale Abklingzeit Eurer Zauber 'Exorzismus' und 'Heiliger Zorn' um 0.5 Sek.\nTrefferchance: Erhöht die Stärke des Trägers 15 Sek. lang um 200." }
