entries[240924] = { ["name"] = "Stangenaxt der Bestie", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n296 - 444 Schaden Tempo 3.40\n(108.82 Schaden pro Sekunde)\n+40 Beweglichkeit\n+13 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Der Effekt 'Feuer konzentrieren' gewährt Euch und Eurem Begleiter jetzt 20 Sek. lang um 4% erhöhten Schaden pro verbrauchtem Stapel.\nAnlegen: +756 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt." }
entries[240925] = { ["name"] = "Experiment 800M", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n159 - 297 Schaden Tempo 3.50\n(65.14 Schaden pro Sekunde)\n+10 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\nBenutzen: Verwandelt Euch für 20 Sek. in eine scharlachrote Kanone, sodass Eure Distanzangriffe Explosionen hervorrufen und allen Gegnern innerhalb von 8 Metern um Eurer Ziel 386 bis 472 Feuerschaden zufügen. (2 Min Abklingzeit)" }
entries[240936] = { ["name"] = "Inaktiver Aschenbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n155 - 233 Schaden Tempo 3.00\n(64.67 Schaden pro Sekunde)\nBenötigt Stufe 60\nBenutzen: Versucht, Kontakt zum Willen des Aschenbringers aufzunehmen. (4 Min Abklingzeit)\nAnlegen: Der Träger wird vom Willen des Aschenbringers erfüllt.\n\"In seiner aktuellen Form ist es nichts als eine Klinge...\"" }
entries[240945] = { ["name"] = "Stück von Carries Apfelkuchen", ["text"] = "Benutzen: Stellt im Verlauf von 18 Sek. 61.2 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Obwohl der Kuchen in drei gleich große Stücke geschnitten wurde, habt Ihr doch irgendwie das kleinste Stück bekommen.\"" }
