entries[240998] = { ["name"] = "Einschläfernde Klinge", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Dolch\n33 - 134 Schaden Tempo 2.00\n(41.75 Schaden pro Sekunde)\n+11 Ausdauer\n+10 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\nBenutzen: Euer nächster regulärer Nahkampfangriff innerhalb von 20 Sek. verursacht Arkanschaden in Höhe des 2-Fachen Eurer Zaubermacht und lässt das Ziel 20 Sek. lang schlafen. (2 Min Abklingzeit)" }
entries[241001] = { ["name"] = "Tyrs Fall", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Streitkolben\n39 - 160 Schaden Tempo 2.40\n(41.46 Schaden pro Sekunde)\n+9 Ausdauer\n+17 Intelligenz\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\nAnlegen: Wenn Ihr regelmäßigen Schaden verursacht, besteht eine Chance von 5%, dass Zauberschaden und Heilung 15 Sek. lang um 120 erhöht werden. (Procchance: 5%)" }
entries[241002] = { ["name"] = "Überreste der Roten", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Schwert\n39 - 160 Schaden Tempo 2.40\n(41.46 Schaden pro Sekunde)\n+5 Ausdauer\n+10 Intelligenz\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht Euer Zaubertempo um 2%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\nAnlegen: Wenn Ihr nicht-regelmäßigem Feuerschaden verursacht, besteht eine Chance von 5%, dass sich Euer verursachter Feuerschaden 15 Sek. lang um 5% erhöht. (Procchance: 5%)" }
entries[241003] = { ["name"] = "Trugbild, Rute der Illusionen", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n200 - 279 Schaden Tempo 3.60\n(66.53 Schaden pro Sekunde)\n+12 Ausdauer\n+28 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Euer Zaubertempo um 2%.\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung um bis zu 169.\nAnlegen: Chance, mit einem Schadenszauber zu treffen, der auf Eurem Ziel ein Trugbild erzeugt, das Gegnern in der Nähe 30 Sek. lang Arkanschaden zufügt. (Procchance: 10%, 30s Abklingzeit)\nBenutzen: Tauscht Plätze mit Eurem Trugbild. (2 Min Abklingzeit)" }
entries[241004] = { ["name"] = "Verwirrung", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n159 - 296 Heiligschaden Tempo 1.50\n(151.67 Schaden pro Sekunde)\n-10 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 30.\nAnlegen: Die Reichweite Eurer Zauber 'Gedankenschinden', 'Feuerschlag' und 'Blutsauger' ist 10 Meter größer, aber 'Gedankenschinden' verlangsamt Gegner nicht mehr." }
entries[241006] = { ["name"] = "Spitze der Opferung", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Streitkolben\n39 - 160 Schaden Tempo 2.40\n(41.46 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht Euer Zaubertempo um 2%.\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 317 Gesundheit und den verursachten Schaden um bis zu 106.\nBenutzen: Während Ihr mehr als 30% Gesundheit habt, ist Eure Heilung um 200 erhöht, aber dafür opfert Ihr bei jeder Heilung 5% Eurer gesamten Gesundheit. Während dieser Effekt bei Euch aktiv ist, werdet Ihr nur durch direkte, nicht regelmäßige Heilzauber geheilt. (Umgeschalteter Effekt) (10 Sek. Abklingzeit)" }
entries[241008] = { ["name"] = "Geißelung", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n187 - 263 Schaden Tempo 3.60\n(62.50 Schaden pro Sekunde)\n+20 Ausdauer\n+30 Intelligenz\n+21 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 317 Gesundheit und den verursachten Schaden um bis zu 106.\nAnlegen: Schadenszauber, die gegen Gegner eingesetzt werden, geißeln diese 20 Sek. lang. Wann immer sie Schaden verursachen, wird ihr Ziel um 3% seiner maximalen Gesundheit geheilt. Hält 20 Sek. lang oder für bis zu 10 Treffer an. (60 Sek. Abklingzeit) (1Min. Abklingzeit)" }
entries[241011] = { ["name"] = "Großstab der Treue", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n200 - 279 Schaden Tempo 3.60\n(66.53 Schaden pro Sekunde)\n+16 Ausdauer\n+20 Intelligenz\n+30 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Euer Zaubertempo um 4%.\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 317 Gesundheit und den verursachten Schaden um bis zu 106.\nAnlegen: Wenn sich keine Gegner innerhalb von 20 Metern um Euch herum befinden, werden alle Gruppenmitglieder innerhalb von 20 Metern alle 3 Sek. um 125 Gesundheit geteilt. Eine Gruppe kann immer nur einem Spielercharakter gleichzeitig die Treue schwören." }
