entries[241037] = { ["name"] = "Verworfenes Experiment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Bewegungsgeschwindigkeit um 4%.\nBenutzen: Nachdem Ihr das Experiment getrunken habt, erhöhen Nahkampf- oder Distanzangriffe Euer Angriffstempo 30 Sek. lang um 2%. Dieser Effekt ist bis zu 15-mal stapelbar. (2 Min Abklingzeit)" }
entries[241038] = { ["name"] = "Sir Dornels Didgeridoo", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 60\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 2%.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\nBenutzen: Das Spielen des Didgeridoos beschwört ein zufälliges Wildtier an Eure Seite und erhöht 30 Sek. lang Eure körperlichen Fähigkeiten. Kann nur im Kampf verwendet werden. (2 Min Abklingzeit)" }
entries[241039] = { ["name"] = "Infusion der Seelen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Paladin , Priester , Schamane , Magier , Hexenmeister , Druide\nBenötigt Stufe 60\nAnlegen: Erhöht Euer Zaubertempo um 4%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 26.\nAnlegen: Die globale Abklingzeit Eurer nicht waffenbasierten Schadenszauber kann durch Zaubertempo um bis zu 0.5 Sek. verringert werden." }
