entries[241191] = { ["name"] = "Formel: Waffe - Oberster Kreuzzügler", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (280)\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie oft bei Nahkampfangriffen 350 bis 450 Gesundheit heilt und die Stärke 20 Sek. lang um 120 erhöht.\n\"Lehrt Euch, wie man eine Waffe dauerhaft so verzaubert, dass sie gelegentlich ihren Benutzer mit unfassbarer Stärke segnet.\"" }
entries[241195] = { ["name"] = "Formel: Zweihandwaffe - Oberster Arkanist", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (280)\nEine Zweihandnahkampfwaffe dauerhaft verzaubern, sodass bei einem Treffer mit einem Zauber häufig 350 bis 450 Mana wiederhergestellt und die Zaubermacht 20 Sek. lang um 140 erhöht wird.\n\"Lehrt Euch, wie man eine zweihändige Nahkampfwaffe dauerhaft so verzaubert, dass sie gelegentlich ihren Benutzer mit erhöhter Zaubermacht segnet.\"" }
entries[241201] = { ["name"] = "Formel: Waffe - Oberster Zauberer", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (280)\nEine Nahkampfwaffe dauerhaft verzaubern, sodass bei einem Treffer mit einem Zauber häufig 350 bis 450 Mana wiederhergestellt und die Zaubermacht 20 Sek. lang um 70 erhöht wird.\n\"Lehrt Euch, wie man eine Nahkampfwaffe dauerhaft so verzaubert, dass sie gelegentlich ihren Benutzer mit erhöhter Zaubermacht segnet.\"" }
