entries[241650] = { ["name"] = "Erheblicher verfärbter Heiltrank", ["text"] = "Benötigt Stufe 60\nBenutzen: Stellt sofort 3750 bis 4250 Gesundheit wieder her, allerdings erleidet Ihr im Laufe der Zeit Schaden in Höhe von 75% des Werts.\n\nDie Symptome dieses Effekts können sich als Gift für 6 Sek. oder als Krankheit für 12 Sek. zeigen. (2 Min Abklingzeit)" }
