entries[242018] = { ["name"] = "Blutendes Pestlandherz", ["text"] = "Questgegenstand\n\"Eine ungewöhnlich prächtige Blume, wenn man bedenkt, welcher Region sie entstammt. Sie ist trotz der Pest in der Lage, zu gedeihen.\"" }
