entries[242266] = { ["name"] = "Welt der Schutzkraft", ["text"] = "Wird beim Aufheben gebunden\n\"Von vorne bis hinten mit ausführlichen Aufzeichnungen zu allerlei magischen Schutzen gefüllt. Kurioserweise leuchtet das Buch schwach.\"" }
entries[242267] = { ["name"] = "Vom Arkanist zum Erzmagier", ["text"] = "Wird beim Aufheben gebunden\n\"Eine selbstbeweihräuchernde Autobiografie von einem Autor, der zu irrelevant ist, um genannt zu werden. Interessanterweise surrt das Buch aufgrund eines aufmerksamkeitssuchenden Zaubers.\"" }
entries[242268] = { ["name"] = "Verzaubert einen Kreuzfahrer", ["text"] = "Wird beim Aufheben gebunden\n\"Eine unterhaltsame Kurzgeschichte, die schnell dem Wahnsinn verfällt, bevor sie darin endet, dass der Antagonist alles bekommt, was er möchte. Witzigerweise strahlt das Buch vor Kraft.\"" }
