entries[242436] = { ["name"] = "Putress' Tagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: (Unbekannt #686) (1)\nIn Schildhand geführt\n-5 Stärke\n-5 Beweglichkeit\n+1 Ausdauer\nKlassen: Priester , Magier , Hexenmeister , Druide\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 30.\nBenutzen: Fügt Putress' Tagebuch die erste Seite hinzu." }
entries[242465] = { ["name"] = "Fragment des angerempelten Kelchs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt 3 Bruchstücke zusammen, um den Kelch des Kreuzfahrers zu reparieren." }
entries[242793] = { ["name"] = "Tragbare Kanone", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Stufe 60\nAnlegen: Erhöht die kritische Trefferchance aller Eurer Angriffe und Zauber um 3%.\nAnlegen: Verbessert Eure Chance auf Treffer mit allen Zaubern und Angriffen um 2%.\nBenutzen: Ladet Euch selbst in eine Kanone. Was soll schon schiefgehen? (1 Min, 30 Sek. Abklingzeit)" }
entries[243010] = { ["name"] = "Verderbter Aschenbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n26 - 39 Schaden Tempo 3.60\n(9.03 Schaden pro Sekunde)\n-25 Ausdauer\nHaltbarkeit 120 / 120\n\"Klinge des Scharlachroten Hochlords\"" }
