entries[244460] = { ["name"] = "Caladschneide", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n339 - 509 Schaden Tempo 3.90\n(108.72 Schaden pro Sekunde)\n+50 Stärke\n+15 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eurer Angriffstempo um 2%.\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nBenutzen: Die Caladschneide wird 20 Sek. lang erneut von der Erde verschlungen, wodurch die Bewegungsgeschwindigkeit um 50% verringert wird. Wenn Ihr Euch bewegt, erhöht sich Eure Bewegungsgeschwindigkeit alle 2 Sekunden. Wenn Ihr in einen Gegner kracht, fügt Ihr diesem 300 bis 2700 Feuerschaden zu, wobei Ihr alle gegnerischen Spielercharaktere zurückstoßt und diesen Effekt beendet. (2 Min Abklingzeit)\n\"Eine uralte Klinge, die vom Scharlachroten Kreuzzug geheim gehalten wird. Weist leichte Gebrauchsspuren auf.\"" }
entries[245675] = { ["name"] = "Schlüssel für die Gordokinnentür", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[246055] = { ["name"] = "Handschutz der Inquisition", ["text"] = "Geweiht\nWird beim Aufheben gebunden\nHände Platte\n681 Rüstung\n+13 Ausdauer\n+38 Intelligenz\nHaltbarkeit 55 / 55\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Verringert die Chance, dass Eure Angriffe pariert werden oder ihnen ausgewichen wird, um 1%.\nAnlegen: Erhöht Eurer Angriffstempo um 2%.\n\nSchockplatte der Inquisition (0/8)\nGesichtsschutz der Inquisition\nSchulterklappen der Inquisition\nKürass der Inquisition\nKordel der Inquisition\nPlattenbeinschützer der Inquisition\nStampfer der Inquisition\nArmschienen der Inquisition\nHandschutz der Inquisition\n(2) Set : Während 'Verunsicherungstaktik' aktiv ist, gewähren Euer 'Kreuzfahrerstoß' und 'Exorzismus' Euch Heilige Kraft und erhöhen den von Euch verursachten Heiligschaden um 10%. Bis zu 3-mal stapelbar. (100ms Abklingzeit)\n(4) Set : Euer 'Göttlicher Sturm', 'Heiliger Schock' und 'Heiliger Zorn' verbrauchen Eure gesamte Heilige Kraft und verursachen 100% mehr Schaden pro angesammelter Heiliger Kraft. Hat gegen Ziele, die von Spielercharakteren kontrolliert werden, eine Effektivität von 50%.\n(6) Set : Wenn Ihr Heilige Kraft verbraucht, wird Eure Zaubermacht 10 Sek. lang um 8 bis 18% pro verbrauchter Heiliger Kraft erhöht." }
